const test = require('node:test');
const assert = require('node:assert/strict');
const { validTemperature } = require('../temperature.cjs');
test('only finite primitive readings are accepted', () => {
  for (const value of [-273.15,-18,0,0.25,1e100]) assert.equal(validTemperature(value), true);
  for (const value of [NaN,Infinity,-Infinity,'-18','',null,undefined,true,false,new Number(4),{},[]]) {
    assert.equal(validTemperature(value), false);
  }
});

